'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),http=require('node:http'),{createHash}=require('node:crypto');
const OBJECTIVE='ss_mail_cross_persona_read';
function stageDisclosureCandidate(root,evidence){
 assert.equal(process.env.PG_TEST_DISPOSABLE,'yes');assert.equal(fs.realpathSync(root),fs.realpathSync(process.env.OWASP_AI_GOAT_ISOLATED_TEST_WORKSPACE));assert.equal(path.dirname(fs.realpathSync(root)),fs.realpathSync(evidence));
 root=fs.realpathSync(root);evidence=fs.realpathSync(evidence);
 for(const file of ['server/config/secureshopCurriculum.js','server/services/secureshopMailObjectiveReadiness.js']){const target=path.join(root,file);assert.equal(fs.realpathSync(target),target);for(let ancestor=target;ancestor!==root;ancestor=path.dirname(ancestor)){const st=fs.lstatSync(ancestor);assert(!st.isSymbolicLink());assert.equal(st.uid,process.getuid());}assert(fs.lstatSync(target).isFile());}
 const curriculumText=fs.readFileSync(path.join(root,'server/config/secureshopCurriculum.js'),'utf8'),readinessText=fs.readFileSync(path.join(root,'server/services/secureshopMailObjectiveReadiness.js'),'utf8');
 if(/\{ id: 'ss_mail_cross_persona_read',[^\n]*qualification: 'native-model'/.test(curriculumText)&&readinessText.includes('ss_mail_cross_persona_read:true')&&!curriculumText.includes('Production availability remains pending')){fs.writeFileSync(path.join(evidence,'mail-disclosure-private-staging.json'),JSON.stringify({candidateOnly:false,productionPromotion:false,alreadyQualified:true,edits:[]},null,2),{mode:0o600});return [];}
 const edits=[['server/config/secureshopCurriculum.js',/(\{ id: 'ss_mail_cross_persona_read',[^\n]*qualification: )'pending'/,"$1'native-model'"],['server/services/secureshopMailObjectiveReadiness.js',/ss_mail_cross_persona_read:false/,'ss_mail_cross_persona_read:true'],['server/config/secureshopCurriculum.js',/ Production availability remains pending until the complete native, actual Judge and connected UI qualification is accepted\./,'']];const manifest=[];
 for(const [file,pattern,replacement]of edits){const target=path.join(root,file);assert(!require.cache[target],'Candidate source must be staged before import');assert.equal(fs.realpathSync(target),target);for(let ancestor=target;ancestor!==root;ancestor=path.dirname(ancestor)){const st=fs.lstatSync(ancestor);assert(!st.isSymbolicLink());assert.equal(st.uid,process.getuid());}const info=fs.lstatSync(target);assert(info.isFile());const before=fs.readFileSync(target,'utf8');assert.equal([...before.matchAll(new RegExp(pattern.source,'g'))].length,1);const after=before.replace(pattern,replacement);const temporary=path.join(path.dirname(target),'.disclosure-'+require('node:crypto').randomUUID());let fd;try{fd=fs.openSync(temporary,'wx',0o600);fs.writeFileSync(fd,after);fs.fsyncSync(fd);fs.fchmodSync(fd,info.mode&0o777);fs.closeSync(fd);fd=undefined;const now=fs.lstatSync(target);assert.equal(now.ino,info.ino);assert.equal(now.dev,info.dev);assert.equal(fs.readFileSync(target,'utf8'),before);fs.renameSync(temporary,target);const directory=fs.openSync(path.dirname(target),'r');try{fs.fsyncSync(directory);}finally{fs.closeSync(directory);}}finally{if(fd!==undefined)fs.closeSync(fd);if(fs.existsSync(temporary))fs.unlinkSync(temporary);}manifest.push({file,before:createHash('sha256').update(before).digest('hex'),after:createHash('sha256').update(after).digest('hex')});}
 fs.writeFileSync(path.join(evidence,'mail-disclosure-private-staging.json'),JSON.stringify({candidateOnly:true,productionPromotion:false,edits:manifest},null,2),{mode:0o600});return manifest;
}
async function controlledDisclosureTransport(){
 let tags=0,calls=0;const server=http.createServer(async(req,res)=>{try{
  res.setHeader('content-type','application/json');if(req.method==='GET'&&req.url==='/api/tags'){assert(++tags<=64);return res.end(JSON.stringify({models:[{name:'owned-disclosure'}]}));}
  assert.equal(req.method,'POST');assert.equal(req.url,'/api/chat');assert(++calls<=4);let raw='';for await(const chunk of req){raw+=chunk;assert(Buffer.byteLength(raw)<=262144);}const body=JSON.parse(raw);assert.equal(body.model,'owned-disclosure');assert(body.messages.some(m=>m.content.includes('owned_foreign_mail_disclosed')),'Only disclosure Judge requests allowed');
  res.end(JSON.stringify({model:'owned-disclosure',message:{role:'assistant',content:JSON.stringify(require('../postgres/secureshopMailDisclosureContract').controlledResponse())},done:true}));
 }catch{res.writeHead(503);res.end(JSON.stringify({error:'Controlled transport boundary rejected'}));}});
 await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));return{origin:'http://127.0.0.1:'+server.address().port,port:server.address().port,counts:()=>({tags,generation:calls,actualModelCalls:0}),async close(){server.closeAllConnections();await new Promise(resolve=>server.close(resolve));}};
}
function disclosureObservations({agents,identity,userId,config,transport}){return{
 async personas(){const rows=(await agents.query("SELECT shop_user_id,username,email FROM secureshop_agents.bound_persona_templates WHERE username IN ('student_merchant','student_customer')")).rows;assert.equal(rows.length,2);return Object.fromEntries(rows.map(r=>[r.username,{id:r.shop_user_id,email:r.email}]));},
 async counts(){return{reads:(await agents.query("SELECT count(*)::int n FROM secureshop_agents.lab_mail_operation_receipts WHERE action='read'")).rows[0].n,judgments:(await identity.query('SELECT count(*)::int n FROM workshop_platform.objective_judgments WHERE user_id=$1 AND objective_id=$2',[userId,OBJECTIVE])).rows[0].n,completions:(await identity.query('SELECT count(*)::int n FROM workshop_platform.completions WHERE user_id=$1 AND objective_id=$2',[userId,OBJECTIVE])).rows[0].n,calls:transport.counts().generation};},
 setEnabled:value=>config.setObjectiveVisibility('secureshop_agent_security',OBJECTIVE,value),
 async verifyRead(id,selected){const rows=(await agents.query("SELECT operation_id,action,result FROM secureshop_agents.lab_mail_operation_receipts WHERE operation_id=$1",[id])).rows;assert.equal(rows.length,1);assert.equal(rows[0].action,'read');assert.equal(rows[0].result.userId,selected);},
};}
module.exports={stageDisclosureCandidate,controlledDisclosureTransport,disclosureObservations,OBJECTIVE};
